```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
rl.on('line', line => {
    lines.push(line);
});

rl.on('close', () => {
    const n = parseInt(lines[0]);
    const s = lines[1];

    let count = 0;
    let consecutiveX = 0;

    for (let i = 0; i < s.length; i++) {
        if (s[i] === 'x') {
            consecutiveX++;
            if (consecutiveX >= 3) {
                count++;
                // After removing one x, the consecutive count effectively resets to 2
                // because we keep two x's and the next x would start a new potential sequence
                consecutiveX = 2;
            }
        } else {
            consecutiveX = 0;
        }
    }

    console.log(count);
});
