const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
rl.on('line', line => {
    lines.push(line);
});

rl.on('close', () => {
    const n = parseInt(lines[0]);
    const s = lines[1];

    let count = 0;
    let i = 0;
    while (i < n - 2) {
        if (s[i] === 'x' && s[i + 1] === 'x' && s[i + 2] === 'x') {
            count++;
            i += 3; // skip the next two x's after removing one
        } else {
            i++;
        }
    }

    console.log(count);
});
